public class Loops {
    public static void main(String[] args) {
        int[] numbers = {10, 20, 30};
        for (int n : numbers) {           // enhanced for
            System.out.println(n);
        }

        int count = 0;
        do {
            System.out.println("Runs at least once: " + count);
            count++;
        } while (count < 3);

        outer:
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (j == 1) continue outer;    // labeled continue affects the OUTER loop
                System.out.println(i + "," + j);
            }
        }
    }
}
